pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple ERC20 token that allows transferFrom from any address
        address token = address(new SimpleERC20());
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint[] memory values = new uint[](1);
        values[0] = 100;
        // Make sure from has enough balance to transfer 100
        SimpleERC20(token).mintForTest(from, 100);
        // Approve c to spend from's tokens
        vm.prank(from);
        SimpleERC20(token).approve(address(c), 100);
        // Call transfer - reference returns true, buggy returns false
        bool success = c.transfer(from, token, tos, values);
        // The assertion that holds for reference and breaks for buggy
        assertTrue(success);
    }
}

contract SimpleERC20 {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function transferFrom(address from, address to, uint256 amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        require(balanceOf[from] >= amount);
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }

    function approve(address spender, uint256 amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function mintForTest(address user, uint256 amount) public {
        balanceOf[user] = amount;
    }
}

