pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a simple token that tracks sender balances
        Token token = new Token();
        address tokenAddr = address(token);

        // Setup: give some tokens to 'from' address
        address from = address(0x123);
        vm.deal(from, 1 ether);

        // 'to' addresses
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint[] memory amounts = new uint[](1);
        amounts[0] = 100;

        // Mint tokens to 'from' in the token contract
        token.mint(from, 100);

        // Approve the C contract to spend from 'from'
        vm.prank(from);
        token.approve(address(c), 100);

        // Call transfer on C with the token contract address
        // Reference: uses call (not delegatecall) -> reverts if token doesn't have transferFrom?
        // Actually token has transferFrom, so reference succeeds
        // Buggy: uses delegatecall -> modifies C's storage instead
        bool ok;
        try c.transfer(from, tokenAddr, tos, amounts) {
            ok = true;
        } catch {
            ok = false;
        }

        // In the reference version, transferFrom is called via call,
        // so token.balanceOf(to) increases. In the buggy version,
        // delegatecall attempts to modify C's storage (which has no balances),
        // so token.balanceOf(to) stays 0.
        assertEq(token.balanceOf(tos[0]), 100);
    }
}

contract Token {
    mapping(address => uint) public balances;
    mapping(address => mapping(address => uint)) public allowance;

    function mint(address to, uint amount) public {
        balances[to] += amount;
    }

    function approve(address spender, uint amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint amount) public returns (bool) {
        require(allowance[from][msg.sender] >= amount);
        allowance[from][msg.sender] -= amount;
        balances[from] -= amount;
        balances[to] += amount;
        return true;
    }
}

