pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // deploy a simple ERC20 token that tracks balances
        ERC20 token = new ERC20();
        token.mint(address(this), 100);
        // transfer tokens to the contract so it can call transferFrom
        token.transfer(address(c), 100);
        // approve the contract to spend tokens from this address
        token.approve(address(c), 100);
        // prepare arrays: send to one recipient (this address itself)
        address[] memory tos = new address[](1);
        tos[0] = address(this);
        uint[] memory vals = new uint[](1);
        vals[0] = 10;
        // call the transfer function
        bool success = c.transfer(address(this), address(token), tos, vals);
        // reference: after transfer, balance of this should be 100 (since from == to, net change 0)
        // but due to the bug (delegatecall), the token's storage is overwritten, causing balance to become 10
        assertEq(token.balanceOf(address(this)), 100);
    }
}

// Minimal ERC20 token for testing
contract ERC20 {
    mapping(address => uint) public balanceOf;
    mapping(address => mapping(address => uint)) public allowance;

    function mint(address to, uint amount) public {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint amount) public returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint value) public returns (bool) {
        require(allowance[from][msg.sender] >= value);
        allowance[from][msg.sender] -= value;
        balanceOf[from] -= value;
        balanceOf[to] += value;
        return true;
    }

    function transfer(address to, uint value) public returns (bool) {
        balanceOf[msg.sender] -= value;
        balanceOf[to] += value;
        return true;
    }
}

